class ButtonHandler {
  count = 0;
  // Class Field with Arrow Function
  handleClick = () => {
    this.count++;
  }
}

class Counter {
  constructor() {
    this.count = 0;
  }
  // Arrow Function defined as Class Field
  increment = () => {
    return ++this.count;
  }
}

const counter = new Counter();
const fakeContext = { count: 100 };

// Attempt to change 'this' context
console.log(counter.increment.call(fakeContext));

